import type { ReelsMedia } from '../types/global';
import '../ExtPay.js';

import { saveHighlights, saveProfileReel, saveReels, saveStories } from './fn';
import { CONFIG_LIST } from '../constants';

// Initialize ExtPay
const ExtPay = (self as any).ExtPay;
const extpay = ExtPay('ig-download');
extpay.startBackground();


chrome.runtime.onInstalled.addListener(async () => {
   const result = await chrome.storage.sync.get(CONFIG_LIST);
   CONFIG_LIST.forEach((i) => {
      if (result[i] === undefined) {
         chrome.storage.sync.set({
            [i]: true,
         });
      }
   });
   
   // 初始化下载计数
   const downloadResult = await chrome.storage.local.get(['downloadCount']);
   if (downloadResult.downloadCount === undefined) {
      await chrome.storage.local.set({ downloadCount: 0 });
   }

   // Register daily cleanup alarm
   chrome.alarms.create('daily-cleanup-and-ping', { periodInMinutes: 1440 });
});

chrome.alarms.onAlarm.addListener((alarm) => {
   if (alarm.name === 'daily-cleanup-and-ping' || alarm.name === 'delayed-cleanup') {
      // Check if the extension was actively used in the last 10 minutes
      if (Date.now() - lastActiveTime < 10 * 60 * 1000) {
         // User is active, check again in 10 minutes
         chrome.alarms.create('delayed-cleanup', { delayInMinutes: 10 });
      } else {
         performCleanupAndPing();
      }
   }
});

function performCleanupAndPing() {
   const keysToRemove = [
      'threads',
      'reels',
      'reels_media',
      'highlights_data',
      'reels_edges_data',
      'profile_reels_edges_data',
      'stories_reels_media',
      'stories_user_ids',
      'id_to_username_map',
      'user_profile_pic_url'
   ];

   chrome.storage.local.remove(keysToRemove, () => {
      console.log('Stale Instagram caches cleared to free up memory.');
   });

   // Send ping for WAU tracking
   try {
      const manifest = chrome.runtime.getManifest();
      fetch('https://your-server.com/api/ping', { // Replace with your actual server URL
         method: 'POST',
         headers: {
            'Content-Type': 'application/json',
         },
         body: JSON.stringify({
            action: 'daily_ping',
            version: manifest.version,
            extension: 'ig-download'
         })
      }).catch(() => {
         // Ignore network errors for ping
      });
   } catch (e) {
      // Ignore errors
   }
}

chrome.runtime.onStartup.addListener(() => {
   chrome.storage.local.set({ stories_user_ids: [], id_to_username_map: [] });
});

let lastActiveTime = 0;

chrome.runtime.onMessage.addListener((message, sender, sendResponse: (response?: any) => void) => {
   lastActiveTime = Date.now();
   //  console.log(message);
   const { type, data } = message;
   
   if (type === 'open_url') {
      chrome.tabs.create({ url: data, index: sender.tab!.index + 1 });
      return false;
   }
   
   // 保留打开付费页面的功能作为备用
   if (type === 'open-payment-page') {
      try {
         const extpay = ExtPay('ig-download');
         extpay.openPaymentPage();
         console.log('Payment page opened via background script');
      } catch (error) {
         console.error('Error opening payment page:', error);
      }
      return true;
   }
   
   return false;
});

async function addThreads(data: any[]) {
   const { threads } = await chrome.storage.local.get(['threads']);
   const newMap = new Map(threads);
   for (const item of data) {
      const code = item?.post?.code;
      if (code) {
         newMap.set(code, item);
      }
   }
   await chrome.storage.local.set({ threads: Array.from(newMap) });
}

function findValueByKey(obj: Record<string, any>, key: string): any {
   for (const property in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, property)) {
         if (property === key) {
            return obj[property];
         } else if (typeof obj[property] === 'object') {
            const result = findValueByKey(obj[property], key);
            if (result !== undefined) {
               return result;
            }
         }
      }
   }
}

chrome.runtime.onMessageExternal.addListener((message, sender, sendResponse) => {
   lastActiveTime = Date.now();
   // console.log(message, sender);

   const { type, data, api } = message;

   if (sender.origin === 'https://www.threads.net') {
      if (type === 'threads_searchResults') {
         data
            .split(/\s*for\s+\(;;\);\s*/)
            .filter((_: any) => _)
            .map(async (i: any) => {
               try {
                  const result = findValueByKey(JSON.parse(i), 'searchResults');
                  if (result && Array.isArray(result.edges)) {
                     await addThreads(result.edges.map((i: any) => i.node.thread.thread_items).flat());
                  }
               } catch {}
            });
      } else {
         addThreads(data);
      }
      return false;
   }

   (async () => {
      if (type === 'stories') {
         const { stories_user_ids, id_to_username_map } = await chrome.storage.local.get(['stories_user_ids', 'id_to_username_map']);
         const nameToId = new Map(stories_user_ids);
         const idToName = new Map(id_to_username_map);
         nameToId.set(data.username, data.user_id);
         idToName.set(data.user_id, data.username);
         await chrome.storage.local.set({ stories_user_ids: Array.from(nameToId), id_to_username_map: Array.from(idToName) });
      } else {
         try {
            const jsonData = JSON.parse(data);

            switch (api) {
               case 'https://www.instagram.com/api/graphql':
                  saveStories(jsonData);
                  break;
               case 'https://www.instagram.com/graphql/query':
                  saveHighlights(jsonData);
                  saveReels(jsonData);
                  saveStories(jsonData);
                  saveProfileReel(jsonData);
                  break;
               // presentation stories in home page top
               case '/api/v1/feed/reels_media/?reel_ids=':
                  const { reels, reels_media } = await chrome.storage.local.get(['reels', 'reels_media']);
                  const newArr = (reels_media || []).filter(
                     (i: ReelsMedia.ReelsMedum) => !(jsonData as ReelsMedia.Root).reels_media.find((j) => j.id === i.id)
                  );
                  chrome.storage.local.set({
                     reels: Object.assign({}, reels, data.reels),
                     reels_media: [...newArr, ...jsonData.reels_media],
                  });
                  break;
            }
         } catch {}
      }
      sendResponse();
   })();

   return true;
});
